const MQ=window.MQPrimary;if(!MQ)return;
const H=MQ.H;const {R,P,ch,num,txt,order,tf,bank,pairs,sort,seq,mix,pickN,shuffle,SVG,nf,enLettres,enLettresTrad}=H;
const C=(d,u,ex,m,a,r,obj)=>({d,u,ex,m,a,r,obj});
const say=w=>({t:w,l:'fr-FR'});

