  [{t:'Les couleurs',h:`<p>🔴 ${en('red')} · 🔵 ${en('blue')} · 🟢 ${en('green')} · 🟡 ${en('yellow')} · 🟠 ${en('orange')} · 🟣 ${en('purple')} · ⚫ ${en('black')} · ⚪ ${en('white')} · 🩷 ${en('pink')} · 🟤 ${en('brown')}</p><p>${en('What colour is it?')} = De quelle couleur est-ce ? – ${en('It’s red.')} = C’est rouge.</p>`}],
